#!/usr/bin/env bash
set -euo pipefail

SCRIPT_ROOT="$(dirname "$(realpath "$0")")"

known_not_tangled=(
	LICENSE

	# Generated by Git.
	.gitmodules

	# Generated by Niv.
	nix/sources.json
	nix/sources.nix

	# Images.
	base/image/PNG-Gradient.png

	# Bibliographical references (CSL JSON format).
	base/bib.json

	# CSL styles submodule repo.
	base/csl-styles

	.vale/styles/.gitkeep
)

tangled_files()
{
	unset GIT_LITERAL_PATHSPECS
	git -C "${SCRIPT_ROOT}" grep -E '^#\+header: :tangle' -- '*.org' \
		| awk '{print $3}' \
		| sort -u
}

tracked_files()
{
	git -C "${SCRIPT_ROOT}" ls-files \
		| grep -v '\.\(html\|org\)$'
}

main()
{
	echo >&2 -n "$0: checking tangled vs tracked files... "

	# (ref:tangled-tracked-diff)
	if diff -u \
		<(printf '%s\n' "$(tangled_files)" "${known_not_tangled[@]}" | sort) \
		<(tracked_files); then

		echo >&2 "OK"
	else
		echo >&2 "$0: failed"
		return 1
	fi
}

main "$@"
